import os,json,subprocess
from pathlib import Path
terms=["/etc/lowcost-europa","/srv/lowcost-europa","/var/lib/lowcost-europa","/var/backups/lowcost-europa","/root/project-secrets/lowcost-europa","/srv/projects/lowcost-europa"]
units=sorted(Path("/etc/systemd/system").glob("lowcost-europa*.service"))
scripts=[Path("/usr/local/sbin")/x for x in ("lowcost-europa-backup","lowcost-europa-offsite-backup","lowcost-europa-offsite-backup-health","project-secrets-offsite-backup")]
out={"units":{},"scripts":{},"project":{}}
for p in units:
 try:
  if not p.is_file() or p.is_symlink():continue
  b=p.read_bytes()
  out["units"][p.name]={"ref_counts":{t:b.count(t.encode()) for t in terms},"size":len(b)}
 except OSError:pass
for p in scripts:
 try:
  if not p.is_file() or p.is_symlink():continue
  b=p.read_bytes()
  out["scripts"][p.name]={"ref_counts":{t:b.count(t.encode()) for t in terms},"size":len(b),"mode":oct(p.stat().st_mode&0o777)}
 except OSError:pass
for rel in ("backups","data","private","private/systemd-env","archive","www"):
 p=Path("/srv/projects/lowcost-europa")/rel
 out["project"][rel]={"exists":p.is_dir() and not p.is_symlink(),"uid":p.stat().st_uid if p.exists() else None}
print(json.dumps(out,sort_keys=True))
